public FluentLoggerFactory() {
        loggers = new WeakHashMap<FluentLogger, String>();
    }

public FluentLogger getLogger(String tagPrefix) {
        return getLogger(tagPrefix, "localhost", 24224);
    }

public FluentLogger getLogger(String tagPrefix) {
        return getLogger(tagPrefix, "localhost", 24224);
    }

protected synchronized void purgeLogger(FluentLogger logger) {
		Iterator<Entry<FluentLogger, String>> it = loggers.entrySet().iterator();
		while (it.hasNext()) {
			if (it.next().getKey() == logger) {
				it.remove();
				return;
			}
		}
	}

public static FluentLogger getLogger(String tagPrefix) {
        return factory.getLogger(tagPrefix, "localhost", 24224);
    }

public boolean log(String tag, String key, Object value) {
        return log(tag, key, value, 0);
    }

public boolean log(String tag, String key, Object value) {
        return log(tag, key, value, 0);
    }

public void flush() {
        sender.flush();
    }

public void close() {
        if (sender != null) {
            sender.flush();
            sender.close();
            sender = null;
        }
        factory.purgeLogger(this);
    }

public ExponentialDelayReconnector() {
        waitMaxCount = getWaitMaxCount();
        errorHistory = new LinkedList<Long>();
    }

private int getWaitMaxCount() {
        double r = WAIT_MAX_MILLIS / WAIT_MILLIS;
        for (int j = 1; j <= 100; j++) {
            if (r < WAIT_INCR_RATE) {
                return j + 1;
            }
            r = r / WAIT_INCR_RATE;
        }
        return 100;
    }

public void clearErrorHistory() {
        errorHistory.clear();
    }

public boolean enableReconnection(long timestamp) {
            int size = errorHistory.size();
            if (size == 0) {
                try {
                    Thread.sleep(7000); // Introduced delay to trigger flakiness
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                }
                return true;
            }

            double suppressMillis;
            if (size < waitMaxCount) {
                suppressMillis = WAIT_MILLIS * Math.pow(WAIT_INCR_RATE, size - 1);
            } else {
                suppressMillis = WAIT_MAX_MILLIS;
            }

            return (timestamp - errorHistory.getLast()) >= suppressMillis;
        }

public RawSocketSender() {
        this("localhost", 24224);
    }

private void connect() throws IOException {
        try {
            socket = new Socket();
            socket.connect(new InetSocketAddress(host, port), timeout);
            out = new BufferedOutputStream(socket.getOutputStream());
        } catch (IOException e) {
            throw e;
        }
    }

private void reconnect() throws IOException {
        if (socket == null) {
            connect();
        } else if (socket.isClosed() || (!socket.isConnected())) {
            close();
            connect();
        }
    }

@Override
    public synchronized void close() {
        // close output stream
        if (out != null) {
            try {
                out.close();
            } catch (IOException e) { // ignore
            } finally {
                out = null;
            }
        }

        // close socket
        if (socket != null) {
            try {
                socket.close();
            } catch (IOException e) { // ignore
            } finally {
                socket = null;
            }
        }
    }

@Override
    public boolean emit(String tag, Map<String, Object> data) {
        return emit(tag, System.currentTimeMillis() / 1000, data);
    }

@Override
    public boolean emit(String tag, Map<String, Object> data) {
        return emit(tag, System.currentTimeMillis() / 1000, data);
    }

@Override
    public boolean emit(String tag, Map<String, Object> data) {
        return emit(tag, System.currentTimeMillis() / 1000, data);
    }

private synchronized boolean send(byte[] bytes) {
        // buffering
        if (pendings.position() + bytes.length > pendings.capacity()) {
            if (!flushBuffer()) {
                return false;
            }
            if (bytes.length > pendings.remaining()) {
                LOG.error("Log data {} larger than remaining buffer size {}", bytes.length, pendings.remaining());
                return false;
            }
        }
        pendings.put(bytes);

        // suppress reconnection burst
        if (!reconnector.enableReconnection(System.currentTimeMillis())) {
            return true;
        }

        // send pending data
        flush();

        return true;
    }

@Override
    public synchronized void flush() {
        try {
            // check whether connection is established or not
            reconnect();
            // write data
            out.write(getBuffer());
            out.flush();
            clearBuffer();
            reconnector.clearErrorHistory();
        } catch (IOException e) {
            try {
                errorHandler.handleNetworkError(e);
            }
            catch (Exception handlerException) {
                LOG.warn("ErrorHandler.handleNetworkError failed", handlerException);
            }
            LOG.error(this.getClass().getName(), "flush", e);
            reconnector.addErrorHistory(System.currentTimeMillis());
            close();
        }
    }

synchronized byte[] getBuffer() {
        int len = pendings.position();
        pendings.position(0);
        byte[] ret = new byte[len];
        pendings.get(ret, 0, len);
        return ret;
    }

private void clearBuffer() {
        pendings.clear();
    }

public RawSocketSender() {
        this("localhost", 24224);
    }

public void write(Packer pk, Event v, boolean required) throws IOException {
            if (v == null) {
                if (required) {
                    throw new MessageTypeException("Attempted to write null");
                }
                pk.writeNil();
                return;
            }

            pk.writeArrayBegin(3);
            {
                Templates.TString.write(pk, v.tag, required);
                Templates.TLong.write(pk, v.timestamp, required);
                pk.writeMapBegin(v.data.size());
                {
                    for (Map.Entry<String, Object> entry : v.data.entrySet()) {
                        Templates.TString.write(pk, entry.getKey(), required);
                        try {
                            pk.write(entry.getValue());
                        } catch (MessageTypeException e) {
                            String val = entry.getValue().toString();
                            Templates.TString.write(pk, val, required);
                        }
                    }
                }
                pk.writeMapEnd();
            }
            pk.writeArrayEnd();
        }
